import{_ as a,o,c as i,a2 as r}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Administracao","description":"","frontmatter":{"status":"rascunho","tipo":"modulo","area":"administracao","atualizado_em":"2026-08-03T00:00:00.000Z"},"headers":[],"relativePath":"planejamento/modulos/administracao.md","filePath":"planejamento/modulos/administracao.md","lastUpdated":null}'),s={name:"planejamento/modulos/administracao.md"};function l(d,e,t,c,n,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="administracao" tabindex="-1">Administracao <a class="header-anchor" href="#administracao" aria-label="Permalink to &quot;Administracao&quot;">​</a></h1><h2 id="objetivo" tabindex="-1">Objetivo <a class="header-anchor" href="#objetivo" aria-label="Permalink to &quot;Objetivo&quot;">​</a></h2><p>Gerenciar estruturas internas do painel, usuarios, cargos, calendario, atividades, tarefas e revisoes administrativas.</p><h2 id="escopos-atuais" tabindex="-1">Escopos Atuais <a class="header-anchor" href="#escopos-atuais" aria-label="Permalink to &quot;Escopos Atuais&quot;">​</a></h2><ul><li>Usuarios.</li><li>Cargos.</li><li>Calendario.</li><li>Atividades.</li><li>Tarefas.</li><li>Revisao de formularios.</li></ul><h2 id="funcionalidades" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades" aria-label="Permalink to &quot;Funcionalidades&quot;">​</a></h2><ul><li>Criar usuarios.</li><li>Atualizar acesso de usuarios.</li><li>Desativar usuarios.</li><li>Criar, editar e remover cargos.</li><li>Criar e editar eventos de calendario.</li><li>Criar e editar atividades.</li><li>Criar, editar, concluir, revisar e desativar tarefas.</li><li>Aprovar ou rejeitar formularios recebidos.</li></ul><h2 id="arquivos-envolvidos" tabindex="-1">Arquivos Envolvidos <a class="header-anchor" href="#arquivos-envolvidos" aria-label="Permalink to &quot;Arquivos Envolvidos&quot;">​</a></h2><ul><li>Pagina: <code>resources/js/pages/private/Administration.svelte</code>.</li><li>Controller de pagina: <code>AdministrationPageController</code>.</li><li>Controllers de recurso: <code>UserController</code>, <code>RoleController</code>, <code>CalendarController</code>, <code>ActivityController</code>, <code>TaskController</code>.</li><li>Invokes: <code>CompleteTaskController</code>, <code>DeactivateTaskController</code>, <code>DeactivateUserController</code>, <code>ApproveFormSubmissionController</code>, <code>RejectFormSubmissionController</code>.</li><li>Filters: <code>UserFilter</code>, <code>RoleFilter</code>, <code>PermissionFilter</code>, <code>CalendarFilter</code>, <code>ActivityFilter</code>, <code>TaskFilter</code>, <code>FormSubmissionFilter</code>.</li><li>Models: <code>User</code>, <code>Role</code>, <code>Calendar</code>, <code>Activity</code>, <code>Task</code>, <code>FormSubmission</code>.</li></ul><h2 id="permissoes" tabindex="-1">Permissoes <a class="header-anchor" href="#permissoes" aria-label="Permalink to &quot;Permissoes&quot;">​</a></h2><ul><li><code>administration.module.view</code> controla acesso ao modulo no menu.</li><li>Recursos usam policies dedicadas: <code>UserPolicy</code>, <code>RolePolicy</code>, <code>CalendarPolicy</code>, <code>ActivityPolicy</code>, <code>TaskPolicy</code>.</li><li>Revisao de formularios usa permissoes como <code>form.submission.list</code> e <code>form.submission.review</code>.</li></ul><h2 id="riscos" tabindex="-1">Riscos <a class="header-anchor" href="#riscos" aria-label="Permalink to &quot;Riscos&quot;">​</a></h2><ul><li>Este modulo concentra muitas responsabilidades administrativas.</li><li>Alteracoes de permissao podem afetar varios widgets ao mesmo tempo.</li><li>O fluxo de tarefas precisa de status bem definidos para evitar ambiguidade entre pendente, revisao, concluida e desativada.</li></ul><h2 id="planejamento" tabindex="-1">Planejamento <a class="header-anchor" href="#planejamento" aria-label="Permalink to &quot;Planejamento&quot;">​</a></h2><ul><li>[ ] Documentar permissoes por recurso.</li><li>[ ] Separar tarefas operacionais de tarefas editoriais, se necessario.</li><li>[ ] Definir fluxo completo de status das tarefas.</li><li>[ ] Mapear telas de cadastro e edicao.</li></ul><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to &quot;Referencias&quot;">​</a></h2><ul><li><a href="./dashboard">dashboard</a></li><li><a href="./../arquitetura">arquitetura</a></li><li><a href="./../decisoes">decisoes</a></li></ul>',17)])])}const p=a(s,[["render",l]]);export{h as __pageData,p as default};
